package models
import("time";"github.com/google/uuid";"gorm.io/gorm")
type Assessment struct{ID uuid.UUID `gorm:"type:uuid;primaryKey" json:"id"`;TeacherAssignmentID uuid.UUID `gorm:"type:uuid;not null;index" json:"teacher_assignment_id"`;Title string `gorm:"size:150;not null" json:"title"`;Type string `gorm:"size:30;not null;index" json:"type"`;MaxScore float64 `gorm:"not null" json:"max_score"`;Weight float64 `gorm:"not null;default:100" json:"weight"`;AssessmentDate time.Time `gorm:"not null;index" json:"assessment_date"`;CreatedAt time.Time `json:"created_at"`;UpdatedAt time.Time `json:"updated_at"`}
func(a *Assessment)BeforeCreate(tx *gorm.DB)error{a.ID=uuid.New();return nil}